"""Generate traceable LaTeX fragments from actual revision CSVs only."""

import csv
import importlib.util
from pathlib import Path

import numpy as np

ROOT = Path(__file__).resolve().parents[2]


def main():
    output = ROOT / "results/tables"
    output.mkdir(exist_ok=True)
    descriptor = ROOT / "results/structural_descriptors/summary.csv"
    lines = [
        "% Generated by analysis/revision/make_tables.py; source: "
        + str(descriptor.relative_to(ROOT)),
        r"\begin{tabular}{llrrrr}",
        r"Dataset & Class & Images & Empty fraction & Mean area fraction & Mean L/A \\",
        r"\hline",
    ]
    for row in csv.DictReader(descriptor.open()):
        lines.append(
            f"{row['dataset']} & {row['class']} & {row['images']} & "
            f"{float(row['empty_class_fraction']):.4f} & "
            f"{float(row['mean_area_fraction']):.4f} & "
            f"{float(row['mean_perimeter_area_nonempty']):.4f} " + r"\\"
        )
    lines.append(r"\end{tabular}")
    (output / "structural_training.tex").write_text("\n".join(lines) + "\n")
    summary = []
    for split in ["validation", "test"]:
        source = ROOT / f"results/official_isic/{split}"
        if not source.exists():
            continue
        for arm in "USF":
            by_seed = []
            for seed in [1, 2, 3]:
                path = source / f"{arm}_seed{seed}/per_case.csv"
                if not path.exists():
                    break
                rows = list(csv.DictReader(path.open()))
                if len(rows) != (100 if split == "validation" else 1000):
                    raise ValueError("incomplete official metric table")
                by_seed.append(rows)
            if len(by_seed) != 3:
                continue
            for metric in [
                "dsc",
                "iou",
                "boundary_f1",
                "hd95",
                "assd",
                "hd95_penalized",
                "assd_penalized",
                "native_jaccard",
                "native_thresholded_jaccard",
            ]:
                means = []
                counts = []
                for rows in by_seed:
                    values = [float(r[metric]) for r in rows if r[metric] != ""]
                    means.append(float(np.mean(values)))
                    counts.append(len(values))
                summary.append(
                    dict(
                        split=split,
                        arm=arm,
                        metric=metric,
                        mean=np.mean(means),
                        seed_sd=np.std(means, ddof=1),
                        valid_counts="/".join(map(str, counts)),
                        source=f"results/official_isic/{split}/{arm}_seed[123]/per_case.csv",
                    )
                )
    if summary:
        with (output / "official_isic_summary.csv").open("w") as stream:
            writer = csv.DictWriter(stream, fieldnames=list(summary[0]), lineterminator="\n")
            writer.writeheader()
            writer.writerows(summary)
        lines = [
            r"\begin{tabular}{lllrrl}",
            r"Split & Arm & Metric & Mean & Seed SD & Valid counts \\",
            r"\hline",
        ]
        for row in summary:
            metric = row["metric"].replace("_", r"\_")
            lines.append(
                f"{row['split']} & {row['arm']} & {metric} & {row['mean']:.6f} & "
                f"{row['seed_sd']:.6f} & {row['valid_counts']} " + r"\\"
            )
        lines.append(r"\end{tabular}")
        (output / "official_isic_summary.tex").write_text("\n".join(lines) + "\n")
    stats = output / "official_isic_primary_statistics.csv"
    if stats.exists():
        lines = [
            r"\begin{tabular}{lrrrrl}",
            r"Metric & Difference & Lower CI & Upper CI & Holm p & SESOI judgement \\",
            r"\hline",
        ]
        for row in csv.DictReader(stats.open()):
            metric = row["metric"].replace("_", r"\_")
            probability = f"{float(row['p_holm']):.6f}" if row["p_holm"] else "--"
            lines.append(
                f"{metric} & {float(row['mean_difference']):.6f} & "
                f"{float(row['ci95_low']):.6f} & {float(row['ci95_high']):.6f} & "
                f"{probability} & {row['practical_judgement']} " + r"\\"
            )
        lines.append(r"\end{tabular}")
        (output / "official_isic_primary_statistics.tex").write_text("\n".join(lines) + "\n")
    if (output / "volume_primary_statistics.csv").exists():
        path = Path(__file__).with_name("write_evidence_fragments.py")
        spec = importlib.util.spec_from_file_location("_bds_evidence_fragments", path)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        module.main()
    if (output / "gate_identity_effects.csv").exists():
        path = Path(__file__).with_name("write_gate_findings.py")
        spec = importlib.util.spec_from_file_location("_bds_gate_findings", path)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        module.main()
    if (ROOT / "results/surface_cdf/summary.csv").exists():
        path = Path(__file__).with_name("write_surface_findings.py")
        spec = importlib.util.spec_from_file_location("_bds_surface_findings", path)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        module.main()
    print("Generated training-descriptor table and", len(summary), "official metric summary rows")


if __name__ == "__main__":
    main()
